// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { BrowserChrome, DemoStage, DockHeader, type Build } from '@/app/demos/stage'

import { CAPTIONS, ICONS, ITEMS, JSX_PEEK, PICKED, SVG_PEEK, type Icon } from './script'

const IMG = ITEMS.findIndex((item) => item.source === 'img')

const build: Build = ({ tl, q, qa, step, final, move, click, scramble, wait, cursorOut }) => {
  step(0)
  tl.fromTo(
    qa('card'),
    { opacity: 0, y: 10 },
    { opacity: 1, y: 0, duration: 0.3, stagger: 0.08, ease: 'power3.out' },
    0.3,
  )
  tl.fromTo(
    qa('pv-path'),
    { drawSVG: '0%' },
    { drawSVG: '100%', duration: 0.9, stagger: 0.12, ease: 'power2.inOut' },
    '<0.2',
  )

  step(1, '+=0.3')
  move(`copy-${PICKED}`)
  click(`copy-${PICKED}`)
  tl.to(q(`copy-${PICKED}-text`), { text: { value: 'Copied', delimiter: '' }, duration: 0.15 }, '<')
  tl.to(q(`card-${PICKED}`), { borderColor: 'rgba(244,114,182,0.6)', duration: 0.2 }, '<')
  tl.fromTo(q('peek'), { opacity: 0, y: 8 }, { opacity: 1, y: 0, duration: 0.3 }, '<')

  step(2, '+=0.6')
  move(`jsx-${PICKED}`)
  click(`jsx-${PICKED}`)
  tl.to(
    q(`copy-${PICKED}-text`),
    { text: { value: 'Copy SVG', delimiter: '' }, duration: 0.15 },
    '<',
  )
  scramble('peek-code', JSX_PEEK, { at: '<', duration: 0.9, chars: 'abcdefghijklmnopqrstuvwxyz' })
  tl.to(q('peek-label'), { text: { value: 'JSX', delimiter: '' }, duration: 0.2 }, '<')
  tl.fromTo(
    q('jsx-ready'),
    { opacity: 0, scale: 0.8 },
    { opacity: 1, scale: 1, duration: 0.3, ease: 'back.out(2.5)' },
    '<0.5',
  )
  move('jsx-ready', { at: '+=0.2' })
  click('jsx-ready')
  tl.to(q('jsx-ready'), { backgroundColor: 'rgba(244,114,182,0.35)', duration: 0.2 }, '<')

  step(3, '+=0.5')
  tl.to(q('peek'), { opacity: 0, duration: 0.2 })
  tl.to(q('jsx-ready'), { opacity: 0, duration: 0.2 }, '<')
  tl.to(q(`card-${PICKED}`), { borderColor: 'var(--demo-tint-8)', duration: 0.2 }, '<')
  tl.to(q(`card-${IMG}`), { borderColor: 'rgba(244,114,182,0.6)', duration: 0.3 }, '<')
  tl.to(
    q('page-logo-img'),
    { outline: '2px solid rgba(244,114,182,0.8)', outlineOffset: 2, duration: 0.3 },
    '<',
  )
  tl.to(q('page-logo-img'), { outline: '2px solid rgba(244,114,182,0)', duration: 0.3 }, '+=1')
  cursorOut('<')
  final()
  wait(1)
}

function Glyph({ icon, d, className }: { icon: Icon; d?: string; className?: string }) {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
      className={className}
      aria-hidden
    >
      {icon.paths.map((path) => (
        <path key={path} data-d={d} d={path} />
      ))}
    </svg>
  )
}

function Page() {
  return (
    <div className="h-full bg-[#fafafa] text-[#111]">
      <div className="flex items-center gap-2 border-b border-black/5 px-4 py-2.5">
        <span
          data-d="page-logo-img"
          className="flex size-4 items-center justify-center rounded bg-[#111] text-[8px] font-bold text-white"
        >
          N
        </span>
        <span className="text-[11px] font-semibold">Northwind</span>
      </div>
      <div className="px-4 pt-4">
        <h3 className="text-[16px] font-bold tracking-tight">Built for busy teams</h3>
        <p className="mt-1 text-[9px] text-[#555]">Everything you need, nothing you don’t.</p>
        <div className="mt-3 grid grid-cols-2 gap-2">
          {ICONS.map((icon) => (
            <div
              key={icon.name}
              className="rounded-lg border border-black/5 bg-white p-2 shadow-sm"
            >
              <Glyph icon={icon} className="size-5 text-[#7c3aed]" />
              <p className="mt-1.5 text-[9.5px] font-semibold">{icon.name}</p>
              <span className="mt-1 block h-1.5 w-4/5 rounded-full bg-black/10" />
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label="SVG Grabber collecting a page’s icons, copying one as SVG and converting it to JSX"
      steps={CAPTIONS}
      build={build}
    >
      <BrowserChrome
        url="https://northwind.app/features"
        panelWidth={252}
        panel={
          <div className="flex h-full flex-col">
            <DockHeader />
            <div className="relative flex min-h-0 flex-1 flex-col gap-1.5 p-2">
              <span className="w-fit rounded-md border border-line-strong px-2 py-0.5 text-[9px] text-ink-soft">
                Try again
              </span>
              <div className="grid grid-cols-2 gap-1.5">
                {ITEMS.map((item, index) => (
                  <div
                    key={item.label}
                    data-d={`card card-${index}`}
                    className="rounded-lg border border-line p-1.5 opacity-0"
                  >
                    <p className="truncate text-[9px] font-medium text-ink">{item.label}</p>
                    <div className="mt-1 flex h-8 items-center justify-center rounded bg-ink/[0.04] text-[var(--accent)]">
                      {item.icon ? (
                        <Glyph icon={item.icon} d="pv-path" className="size-5" />
                      ) : (
                        <span className="text-[9px] text-muted">{item.source}</span>
                      )}
                    </div>
                    <div className="mt-1 flex gap-1 text-[8.5px]">
                      <span
                        data-d={`copy-${index}`}
                        className="rounded border border-line-strong px-1 py-px text-ink-soft"
                      >
                        <span data-d={`copy-${index}-text`}>Copy SVG</span>
                      </span>
                      <span data-d={`jsx-${index}`} className="px-1 py-px text-muted">
                        JSX
                      </span>
                    </div>
                  </div>
                ))}
              </div>
              <span
                data-d="jsx-ready"
                className="w-fit rounded-md border border-[var(--accent)]/60 px-2 py-0.5 text-[9px] text-ink opacity-0"
              >
                Copy JSX
              </span>
              <div
                data-d="peek"
                className="absolute inset-x-2 bottom-2 rounded-md border border-line-strong bg-elevated p-1.5 opacity-0 shadow-xl"
              >
                <p data-d="peek-label" className="text-[8px] uppercase tracking-wider text-muted">
                  SVG
                </p>
                <code
                  data-d="peek-code"
                  className="line-clamp-3 break-all font-mono text-[8px] leading-[11px] text-ink-soft"
                >
                  {SVG_PEEK}
                </code>
              </div>
            </div>
          </div>
        }
      >
        <Page />
      </BrowserChrome>
    </DemoStage>
  )
}
